    "link": "https://www.chinanews.com.cn/cj/2026/10-03/10707558.shtml",
    "pub_date": "2026-10-03 18:24:21",
    "author": "",
    "description": "编者按：为推动党的创新理论“飞入寻常百姓家”，陕西省委网信办与央广网陕西频道联合策划推出“理响中国·质胜新时代”融媒体传播专栏，围绕因地制宜发展新质生产力等党中央重大决策部署与时代核心议题，树立和践行正确政绩观，聚焦陕西各地各行业产业升级、科技创新、乡村振兴、绿色生态等的鲜活实践，打造集短视频、图文产品、音频等于一体的全媒体传播体系，让宏大理论扎根现实、贴近群众，为全面推进中国式现代化贡献智慧与力量。",
