    "link": "https://www.chinanews.com.cn/cj/2026/10-03/10707549.shtml",
    "pub_date": "2026-10-03 18:22:55",
    "author": "",
    "description": "10月3日，以“汾黄交汇 飞云之上”为主题的万荣首届房车露营巡游活动在山西省万荣县启幕。李继旺 摄 中新网运城10月3日电 (高雨晴)房车当“移动观景台”，星空当“露天天花板”，后备箱变成助农小集市，古建与黄河一路“同框”……这个国庆假期，山西万荣把“诗和远方”装上轮子，推出房车体验、星空晚会、沿黄采风、助农展销等活动，吸引房车自驾爱好者及八方游客齐聚后土故里，沉浸式体验文旅新业态，也让假日文旅消费“跑”起来。",
    "content": "10月3日，以“汾黄交汇 飞云之上”为主题的万荣首届房车露营巡游活动在山西省万荣县启幕。李继旺 摄 中新网运城10月3日电 (高雨晴)房车当“移动观景台”，星空当“露天天花板”，后备箱变成助农小集市，古建与黄河一路“同框”……这个国庆假期，山西万荣把“诗和远方”装上轮子，推出房车体验、星空晚会、沿黄采风、助农展销等活动，吸引房车自驾爱好者及八方游客齐聚后土故里，沉浸式体验文旅新业态，也让假日文旅消费“跑”起来。"
