    "pub_date": "2026-10-03 17:54:58",
    "author": "赵紫羽,李博闻",
    "description": "新华社日本名古屋10月3日电（记者赵紫羽、李博闻）3日，在以2:6、4:6输掉名古屋亚运会男单决赛后，第三次征战亚运会的吴易昺说：“亚运会依然是心结，但没有遗憾。” 在中国香港队的黄泽林发出“再见ACE”后，吴易昺没有流露出失望的表情，而是主动走到黄泽林这一侧，和他拥抱。 “今天我觉得对手比我打得更好，我身体也不在最佳状态，我已经拼尽全力，没什么好遗憾和不开心的。我们整个队伍，都应该为团队在今年亚运会取得的成绩而感到骄傲。”受感冒影响，…",
    "content": "新华社日本名古屋10月3日电（记者赵紫羽、李博闻）3日，在以2:6、4:6输掉名古屋亚运会男单决赛后，第三次征战亚运会的吴易昺说：“亚运会依然是心结，但没有遗憾。” 在中国香港队的黄泽林发出“再见ACE”后，吴易昺没有流露出失望的表情，而是主动走到黄泽林这一侧，和他拥抱。 “今天我觉得对手比我打得更好，我身体也不在最佳状态，我已经拼尽全力，没什么好遗憾和不开心的。我们整个队伍，都应该为团队在今年亚运会取得的成绩而感到骄傲。”受感冒影响，吴易昺当天状态并非最佳，在发球和底线相持中都出现了一些失误。 这不是吴易昺第一次…"
