    "description": "新华社日本名古屋10月3日电（记者孙哲）亚奥理事会运动员委员会3日宣布，日本跳高运动员户边直人等四人当选委员会成员。 据介绍，在正在进行的爱知·名古屋亚运会期间，参赛运动员们投票选举出户边直人、哈萨克斯坦速度攀岩选手阿米尔·迈穆拉托夫、卡塔尔女子飞碟射击选手丽姆·阿里·沙尔沙尼和泰国女子步枪运动员丹亚叻·触披汶信进入运动员委员会。 亚奥理事会运动员委员会主席丁宁说：“我期待与大家携手合作，继续努力，让运动员在亚奥理事会中拥有更强的声音。…",
