    "title": "台湾消费者网购大陆商品带动“小三通”跨境电商出口火爆",
    "link": "http://www.news.cn/20261003/de8d34bf48514156b587ffa95af1c1a3/c.html",
    "pub_date": "2026-10-03 17:03:14",
    "author": "李慧颖",
    "description": "新华社福州10月3日电（记者 李慧颖）福州马尾跨境电商监管中心内车流不息，台湾消费者在大陆电商平台网购的商品在此分拣通关，搭乘“小三通”货轮运抵马祖，再运往台湾地区。随着台湾消费者网购大陆商品的热情高涨，两马“小三通”对台跨境电商出口也大幅增长。 海关跨境电商管理平台数据显示，今年前九个月福州海关所属马尾海关监管“小三通”跨境电商出口包裹99.76万票，货运量1.48万吨，同比增长9%。 据介绍，台湾消费者在淘宝天猫等平台购物下单后，商…",
    "content": "新华社福州10月3日电（记者 李慧颖）福州马尾跨境电商监管中心内车流不息，台湾消费者在大陆电商平台网购的商品在此分拣通关，搭乘“小三通”货轮运抵马祖，再运往台湾地区。随着台湾消费者网购大陆商品的热情高涨，两马“小三通”对台跨境电商出口也大幅增长。 海关跨境电商管理平台数据显示，今年前九个月福州海关所属马尾海关监管“小三通”跨境电商出口包裹99.76万票，货运量1.48万吨，同比增长9%。 据介绍，台湾消费者在淘宝天猫等平台购物下单后，商品统一运至海关监管场所，在办结海关手续后，经由“小三通”航线当天运抵马祖，次日就…"
