    "content": "新华社福州10月3日电（记者韦晓睿、郭圻）凉爽的海风拂过木麻黄林，木栈道尽头，视线豁然开朗，大海、沙滩和蓝天尽收眼底。浙江游客雷婉婷举起手机拍下这一幕说：“幽静得很，有种回到大自然的感觉。” 这个国庆假期，越来越多的人把目光投向了节奏更松弛的县域。平潭这座海岛小城，也成了不少游客休闲度假的选择。 假期第一天，壳丘头遗址博物馆迎来了一批外省游客。家长们趁着假期带孩子来感受海岛文化，了解平潭先民的生活。 壳丘头遗址博物馆位于福建省平潭综合实验区苏平片区上攀村，毗邻壳丘头遗址群。该遗址群还包括西营、东花丘、龟山等遗址，为…"
