    "content": "新华社日本名古屋10月3日电（记者李博闻 赵紫羽）中国队选手吴易昺3日在爱知·名古屋亚运会网球男单决赛中，以0:2不敌中国香港队的黄泽林，第二次获得亚运会男单银牌。 黄泽林夺得金牌并收获洛杉矶奥运会参赛资格，这也是中国香港队历史上的亚运会网球首金。 首盘第五局吴易昺被破发，第七局再度被破，以2:6落败。第二盘两人战成4:4后，第九局陷入长时间拉锯，最终黄泽林率先实现破发，并顺利拿下自己的发球局获胜。 赛后，黄泽林扔掉球拍，倒地大喊庆祝，吴易昺绕过网带，拥抱恭喜对手，不停地拍着黄泽林肩膀。 “亚运会（金牌）对我来说是…"
