    "author": "澎湃新闻记者 栾晓娜",
    "description": "如果你熟悉莫言，或者看过《红高粱》，那么对“高密东北乡”这个名字一定不会陌生。高密是山东省辖县级市，曾诞生过晏婴、郑玄、刘墉等历史名人，是莫言的家乡，也是我的家乡。同时，这里还有扑灰年画、泥塑、剪纸、茂腔四项国家级非遗，是这些民间艺术的重要传承地。 2012年，莫言获得诺贝尔文学奖。一夜之间，这座默默无闻的县城迅速“出圈”，一批又一批文学爱好者、媒体、游客接踵而至。此后，高密抓住契机，打造莫言文学、红高粱文化核心IP，并以“文学+影视+…",
    "content": "如果你熟悉莫言，或者看过《红高粱》，那么对“高密东北乡”这个名字一定不会陌生。高密是山东省辖县级市，曾诞生过晏婴、郑玄、刘墉等历史名人，是莫言的家乡，也是我的家乡。同时，这里还有扑灰年画、泥塑、剪纸、茂腔四项国家级非遗，是这些民间艺术的重要传承地。 2012年，莫言获得诺贝尔文学奖。一夜之间，这座默默无闻的县城迅速“出圈”，一批又一批文学爱好者、媒体、游客接踵而至。此后，高密抓住契机，打造莫言文学、红高粱文化核心IP，并以“文学+影视+非遗”为主线，大力推进全域文旅融合，激活乡土文化资源，推动文旅产业提质增效。 景…"
