    "description": "10月1日，国际学术期刊《自然・合成》（Nature Synthesis）刊发了中国科学院金属研究所沈阳材料科学国家研究中心团队的最新成果。研究团队提出一种基于物理化学描述符的多元微量元素设计策略，制备了镁、钙、钛和锆多元微量元素协同无钴高镍正极材料（MD-LNMO），实现3分钟快充至近80%电量。 这是该科研团队在无钴高镍层状氧化物正极材料研究方面取得的重要进展，更重要的是推动正极材料设计从“经验试错”迈向“目标导向”。 正极材料是锂…",
    "content": "10月1日，国际学术期刊《自然・合成》（Nature&nbsp;Synthesis）刊发了中国科学院金属研究所沈阳材料科学国家研究中心团队的最新成果。研究团队提出一种基于物理化学描述符的多元微量元素设计策略，制备了镁、钙、钛和锆多元微量元素协同无钴高镍正极材料（MD-LNMO），实现3分钟快充至近80%电量。 这是该科研团队在无钴高镍层状氧化物正极材料研究方面取得的重要进展，更重要的是推动正极材料设计从“经验试错”迈向“目标导向”。 正极材料是锂电池四大主材之一，也是决定锂电池能量密度、倍率性能、循环寿命和安全性的…"
