    "content": "10月3日，据普睿数智研究中心发布的报告显示，“8.28”新政实施后，今年以来拿地规模较高的典型企业9月份全口径拿地金额约884亿元，核心城市中联合拿地已成为主流拿地方式。 根据报告， 保利发展、华润置地、中海地产、绿城中国9月份拿地规模较7-8月月均水平分别下降57%、25%、60%和79%，但9月平均溢价率超过20%，核心城市优质地块仍是央企的拿地首选；中国金茂、保利置业9月未在土地市场获取土地。 此外，部分地方国企与央企自9月起，在自身深耕区域通过联合拿地的方式积极补充土地储备。 建发房产、厦门国贸在上海、厦…"
