    "description": "北京时间10月3日下午，本届亚运男足季军赛，中国U23男足对阵乌兹别克斯坦U23男足，中国队上下半场两度领先，两度都在半场快结束时刻被扳平，最终两队2比2常规时间战平，随后进行的点球大战里，中国队4比3获胜。 这是中国男足在历届亚运会上获得的第4枚奖牌（前3枚分别是1978年铜牌、1994年银牌、1998年铜牌），也是自2002年釜山亚运会男足比赛改制为U23之后，中国队获得的首枚奖牌。 中国队半决赛先赢后输1比2不敌韩国，未能如199…",
    "content": "北京时间10月3日下午，本届亚运男足季军赛，中国U23男足对阵乌兹别克斯坦U23男足，中国队上下半场两度领先，两度都在半场快结束时刻被扳平，最终两队2比2常规时间战平，随后进行的点球大战里，中国队4比3获胜。 这是中国男足在历届亚运会上获得的第4枚奖牌（前3枚分别是1978年铜牌、1994年银牌、1998年铜牌），也是自2002年釜山亚运会男足比赛改制为U23之后，中国队获得的首枚奖牌。 中国队半决赛先赢后输1比2不敌韩国，未能如1994年广岛亚运会那样打入决赛，但赛后从主教练安东尼奥到球员都表达了三四名决赛要争夺…"
