    "content": "前置：这个主要内容是手动编辑的。 仓库： fib nbio 是以前手搓的，没有精力去手搓支持 HTTP 2/3，它已经不值一提、被我放弃。 fib 的几乎所有代码都由 Claude 生成。支持 TLS、HTTP 1/2/3 和 WebSocket，性能基本超过了几乎所有之前的 Go 库。 在 GitHub Actions CI 的 benchmark 中，fib 在一些场景下比标准库高出几倍的吞吐量并且内存占用更低，性能也基本比 fasthttp、fiber、herz 那些以性能著称的库更好。 与 C/C++/Ru…"
