    "content": "新华社阿布扎比10月3日电（记者温新年 夏晓）阿联酋国家通讯社3日援引阿联酋检方消息报道说，对迪拜航空公司客机驾驶舱冲突事件的调查显示，涉事副驾驶企图实施“恐怖活动”。 阿联酋总检察长哈马德·赛义夫·沙姆西当天表示，副驾驶在飞行途中开始实施其计划，使用应急斧在驾驶舱内袭击机长，并企图控制飞机的飞行操纵系统。 沙姆西说，目前调查仍在继续，以查明事件的全部情况、作案动机等，同时完成技术检查以及对实物和数字证据的分析。最终调查结果将在所有必要程序完成后公布。 9月30日，迪拜航空FZ1073航班从阿联酋迪拜飞往以色列特拉…"
