    "content": "新华社日内瓦10月3日电（记者王其冰）据当地媒体报道，瑞士现任联邦主席帕姆兰2日宣布，将于今年年底辞去联邦委员职务。 帕姆兰2日通过社交媒体向公众发布其辞职决定。他表示自己辞职并非如外界所猜测出于健康原因，而是希望在“充满巨大不确定性的时代”为“新鲜血液”腾出空间。他同时承诺将履职至2026年12月31日。 帕姆兰所在政党、瑞士目前最大政党人民党宣布，帕姆兰继任者、该党新的联邦委员的选举将于12月9日举行。 帕姆兰自2016年起作为瑞士人民党的代表之一，进入瑞士联邦委员会。瑞士联邦委员会是国家最高行政机构，由7名委…"
