    "content": "新华社北京10月3日电（记者周圆）工业和信息化部日前发布的数据显示，今年前8个月，我国电信业务总量稳步增长，5G等网络建设和应用不断推进。其中，截至8月末，5G基站总数达519.5万个，占移动基站总数的39.7%。 数据显示，截至8月末，三家基础电信企业的固定互联网宽带接入用户总数达7.04亿户，比上年末净增1365万户；三家基础电信企业及中国广电的移动电话用户总数达18.49亿户，其中5G移动电话用户达13.11亿户；三家基础电信企业发展移动物联网终端用户30.7亿户，比上年末净增1.82亿户。 移动互联网接入流…"
