    "content": "在2026抖音创作者大会，记者见到了画家史国良。 在中国写实水墨领域，史国良是一个绕不过去的名字。他是中国国家画院一级美术师，师从蒋兆和、黄胄、周思聪等一代大师，作品《刻经》获第23届蒙特卡罗国际现代艺术大奖赛“联合国教科文组织委员会大奖”。 但他并未止步于此，他做短视频，蹲在大集上画卖糖葫芦的大爷，发起“画一百位不同职业的社会工作者”活动，把视频评论区叫成“展览位”。在他看来，美育这件事不会变。 他认为，作为艺术家有义务为社会的美育工作尽一份微薄之力，并尽力把它做好。他把“教”字“藏”起来，通过开设边唱边画、画室…"
