    "content": "最近，55 岁单亲妈妈 Julie，靠每月79美元的精准营养，比每年花200万美元硅谷富豪约翰逊还要年轻，这一事件很快在海外爆火，使得“精准营养” 这一词再次进入公众视野。 但值得注意的是，在如今的国内市场上，深耕这一赛道上的玩家已经屈指可数。要知道，在5、6年前，精准营养那是炙手可热，许多大牌纷纷入局，雀巢旗下个性化补剂品牌Persona在多个线上平台都开设了旗舰店，汤臣倍健也宣称要做定制化维生素产品。 奇怪的是，没过多久，雀巢就关闭了旗下店铺，而后者提出概念产品便再无消息。日本著名品牌FANCL（芳珂）也曾宣布…"
