    "content": "2026年秋季，粤桂苏赣闽冀等多地，都有公立医院参与建设的托育机构揭牌开园。 “家里老人也能照顾孩子，但养育理念可能存在差异。孩子已经出汗，老人还继续添衣服。” “我们和教育部门关注的重点不太一样。”医育结合的托育机构，强调儿童健康、营养、早期学习和安全保障。 南方周末记者 郑彩琳 南方周末实习生 孙旺琪 责任编辑：谭畅 2026年9月28日，广州，悦美乐托育中心乳儿班，工作人员与托育的婴幼儿互动。南方周末记者 郑彩琳 摄 郑恺（化名）出生后，他的爸爸妈妈就开始为托育发愁。两人平日都要上班，老人只能偶尔过来帮忙。 …"
