    "content": "新华社内罗毕10月3日电 综述｜厄尔尼诺“放大”非洲气候风险 新华社记者葛晨 刘佑民 鞠银河 在肯尼亚首都内罗毕，牛奶近期成了超市里的“抢手货”。冷藏鲜奶货架空空荡荡，常温牛奶品种也越来越少，一些超市甚至实施限购措施。肯尼亚农业和畜牧业发展部主管秘书乔纳森·穆埃凯解释，厄尔尼诺到来前，肯尼亚通常会遇到干旱，影响牧场的饲草供应，进而波及牛奶生产。 更大的气候扰动还在后面。世界气象组织9月表示，厄尔尼诺事件已确认出现，预计将在数月内增强为超强厄尔尼诺事件，对全球降雨和温度模式产生重大影响，导致极端天气风险上升。非洲联盟…"
