    "content": "新华社新德里10月3日电 据《印度斯坦时报》3日报道，印度边境安全部队2日在印度北部旁遮普邦印巴边境附近开枪打死两名疑似巴基斯坦人。 报道援引印官员的话称，印边境安全部队人员2日中午在旁遮普邦达尔恩达兰地区发现有人试图越过印巴边境进入印度。印方人员多次警告要求对方停下，但对方“无视并继续向印度一侧移动”，印方人员遂开枪射击，造成两人死亡。印方称两名死者疑似“巴方渗透人员”。 报道说，两名死者身份尚未确认，遗体已移交当地警方进行尸检。 巴基斯坦安全部门消息人士2日说，在巴东部旁遮普省卡苏尔地区印巴边境附近，3名巴村民…"
