    "content": "新华社北京10月3日电（记者田晨旭）北京市气象台10月3日9时发布大风蓝色预警信号：受冷空气影响，预计3日下午至4日傍晚，北京市大部分地区有4级左右偏北风，阵风7级左右，昌平、门头沟、石景山、房山西部、海淀西部阵风可达8级以上。 气象部门介绍，10月3日北京天空云量有所增多，白天还会有分散性小阵雨，雨量整体不大。气温方面，白天最高气温在22摄氏度左右，夜间最低气温在13摄氏度上下。早晚时段体感较凉，外出请及时调整着装，谨防感冒。老年人需防范心脑血管疾病的发生。 据介绍，预计10月4日天空云量仍较多，强劲北风在线，受…"
