    "content": "新华社北京10月3日电 美国联邦航空局（FAA）2日宣布，波音737 MAX客机一款飞行软件存在的问题不影响飞行安全。 联邦航空局在声明中说，经专家组评估，“某些波音737 MAX客机飞行计算机中的一个软件问题不构成安全忧虑”，因为驾驶员可“重新完全控制飞机，机组能获得清晰明确的指示”。 该机构同时表示，如果今后“收到关于这一问题的新信息”，会“考虑采取相应措施”。 2023年6月19日，在法国巴黎近郊布尔歇机场举行的巴黎航展上，一架波音737 MAX飞机进行飞行表演 。新华社记者 高静 摄 路透社援引加拿大西捷航…"
