    "description": "“大家好，我是南翔。以前我叫‘南翔不爱吃饭’，是一名美食博主。最近两年做传统文化以及非遗方面的视频比较多。”在2026抖音创作者大会，记者见到了自媒体博主南翔。 南翔，本名史海峰，以挑战制作高难度菜品和复刻名著中的美食走红网络。2023年，从美食赛道开始转入传统文化赛道，形成了“粉丝说什么，他去做什么”的独特标签。目前，南翔账号全网粉丝量达到6000万。 记者发现，南翔的视频有两个特点。第一个是耗时长，第二个是很拼命。有粉丝说，南翔是唯…",
    "content": "“大家好，我是南翔。以前我叫‘南翔不爱吃饭’，是一名美食博主。最近两年做传统文化以及非遗方面的视频比较多。”在2026抖音创作者大会，记者见到了自媒体博主南翔。 南翔，本名史海峰，以挑战制作高难度菜品和复刻名著中的美食走红网络。2023年，从美食赛道开始转入传统文化赛道，形成了“粉丝说什么，他去做什么”的独特标签。目前，南翔账号全网粉丝量达到6000万。 记者发现，南翔的视频有两个特点。第一个是耗时长，第二个是很拼命。有粉丝说，南翔是唯一一个他不敢催更的博主。南翔坦言，“虽然更新得很慢，但我的诚意是满满的。” 谈到…"
