    "description": "新华社里加10月3日电（记者陈玉芬 孟凡宇）拉脱维亚第15届议会选举3日迎来正式投票日。共有14个政党及政党联盟参加选举，1428名候选人角逐议会100个议席。 拉脱维亚全国各地投票站于当地时间3日8时开放，投票将持续至20时。据拉脱维亚中央选举委员会消息，本次选举在全国共设933个投票站，海外设88个投票站。 参加本次选举的主要政治力量包括现政府执政联盟，即“联合名单”、新统一党、民族联盟以及“绿党”和农民联盟。此外，进步党、拉脱维亚…",
    "content": "新华社里加10月3日电（记者陈玉芬 孟凡宇）拉脱维亚第15届议会选举3日迎来正式投票日。共有14个政党及政党联盟参加选举，1428名候选人角逐议会100个议席。 拉脱维亚全国各地投票站于当地时间3日8时开放，投票将持续至20时。据拉脱维亚中央选举委员会消息，本次选举在全国共设933个投票站，海外设88个投票站。 参加本次选举的主要政治力量包括现政府执政联盟，即“联合名单”、新统一党、民族联盟以及“绿党”和农民联盟。此外，进步党、拉脱维亚第一党、稳定党、和谐中心、新保守党等政党和政治联盟也参加角逐。 根据拉脱维亚选举…"
