    "content": "新华社华盛顿10月2日电 据美国阿克西奥斯新闻网站2日报道，美国总统特朗普当天称，对伊朗的下一步行动“进展顺利”。 当天被媒体问及美国对伊朗的下一步行动时，特朗普回应称其“重大”，并称行动“进展得非常顺利”，“伊朗的情况不妙”。 报道还说，美政府“核心内阁成员”当天在马里兰州总统度假地戴维营举行数小时的闭门会议，讨论伊朗战事及针对沙特阿拉伯同也门胡塞武装冲突的下一步行动。 报道援引多名美官员的话称，此次会议“高度不寻常”，没有对外正式公布。上次举行类似会议是在2025年6月，即以色列对伊朗多地发动大规模空袭的前几日…"
