    "author": "杨华",
    "description": "1度电在四川到底有好多名堂？ 熬得出火锅的麻辣鲜香，载得起蜀道的青绿风光，照得见古蜀的千年文脉，更在芯片和动力之间，攒着四川科创的扎实底气。从市井烟火到智创未来，读懂天府之国的安逸与锋芒。 记者：杨华 画面来源：国网四川省电力公司 新华社音视频部制作",
    "content": "1度电在四川到底有好多名堂？ 熬得出火锅的麻辣鲜香，载得起蜀道的青绿风光，照得见古蜀的千年文脉，更在芯片和动力之间，攒着四川科创的扎实底气。从市井烟火到智创未来，读懂天府之国的安逸与锋芒。 记者：杨华 画面来源：国网四川省电力公司 新华社音视频部制作"
