    "author": "澎湃新闻记者 黄粤涵",
    "description": "当地时间10月2日，美国驻巴西使领馆因“安全问题”暂停线下领事服务。由于这一措施发生在巴西总统大选首轮投票前两天，巴西总统卢拉的竞选团队随后要求巴西高等选举法院将此事纳入对“外国干预”2026年大选的调查。 据新华社援引巴西媒体报道，目前，巴西有关部门已派警力在美国驻巴西大使馆周围维持治安。巴西军警已封锁美国驻圣保罗领事馆附近区域。 当地时间2026年10月2日，巴西圣保罗，美国暂停其驻巴西外交机构的面对面服务，包括大使馆及领事馆。圣保…",
    "content": "当地时间10月2日，美国驻巴西使领馆因“安全问题”暂停线下领事服务。由于这一措施发生在巴西总统大选首轮投票前两天，巴西总统卢拉的竞选团队随后要求巴西高等选举法院将此事纳入对“外国干预”2026年大选的调查。 据新华社援引巴西媒体报道，目前，巴西有关部门已派警力在美国驻巴西大使馆周围维持治安。巴西军警已封锁美国驻圣保罗领事馆附近区域。 当地时间2026年10月2日， 巴西 圣保罗， 美国 暂停其驻 巴西 外交机构的面对面服务，包括大使馆及领事馆。圣保罗亨利·杜兰特大街上已关闭的 美国 领事馆区域外，有两辆警车及四名警…"
