    "title": "中国信保前8个月承保金额同比增长12.6%",
    "link": "https://36kr.com/newsflashes/4009680802992007?f=rss",
    "pub_date": "2026-10-03 13:05:01",
    "author": "",
    "description": "据中国出口信用保险公司，今年前8个月，中国信保扩大出口信用保险覆盖面，承保金额8541.8亿美元，同比增长12.6%；服务客户25.1万家，同比增长5.2%。今年前8个月，中国信保助力培育外贸新动能，新业态和服务贸易承保金额同比分别增长18%和40%；推动内外贸一体化，内贸险承保金额4010.3亿元，同比增长14.1%。 (新华社)",
    "content": "据中国出口信用保险公司，今年前8个月，中国信保扩大出口信用保险覆盖面，承保金额8541.8亿美元，同比增长12.6%；服务客户25.1万家，同比增长5.2%。今年前8个月，中国信保助力培育外贸新动能，新业态和服务贸易承保金额同比分别增长18%和40%；推动内外贸一体化，内贸险承保金额4010.3亿元，同比增长14.1%。 (新华社)"
