    "content": "民政部日前发布提示称，近期一些非法养老App以“民惠通”等为名实施诈骗。不法分子伪造文件、冒充民政部工作人员，宣称可“发放高龄补贴”等，要求先交保险金、保证金、激活费等，或以“签到赚钱”“高额返利”“拉人头返佣”诱导充值投资，最终无法提现。 民政部提示，其从未设立或批准设立“民惠通”等项目，也未推出任何类似产品和相关App，请广大公众提高警惕，不要轻信来源不明的信息和不实宣传，避免上当受骗。对于已经参与或可能遭受损失的用户，建议尽快向属地公安部门报案，避免造成进一步损失；如遇可疑情况，请立即拨打110报警或拨打96…"
