    "content": "当地时间10月2日，新华社记者在以色列本-古里安国际机场现场看到，以色列飞往迪拜的航班已全部取消，机场整体运行维持正常，但客流量较以往明显下降，现场冷清。航班变动打乱了部分旅客行程，不少旅客表达了出行方面的恐惧与不安。 据美国媒体2日报道，消息人士称，在迪拜航空公司客机驾驶舱冲突事件中涉嫌刺伤机长的副驾驶在调查中承认，他的意图是“在以色列坠毁该飞机”。 9月30日，迪拜航空FZ1073航班从阿联酋迪拜飞往以色列特拉维夫途中发生安全事件。据阿联酋媒体报道，该航班副驾驶涉嫌在驾驶舱内刺伤机长，导致客机突然急降。在其他机…"
