    "title": "国庆假期首日上海口岸出入境旅客达13.2万人次，同比增长4.8%",
    "link": "https://36kr.com/newsflashes/4009656474832768?f=rss",
    "pub_date": "2026-10-03 12:33:29",
    "author": "",
    "description": "国庆假期，上海口岸迎来新一轮出入境客流高峰。新民晚报记者从上海边检总站获悉，10月1日，上海口岸出入境旅客达13.2万人次，同比增长4.8%。上海边检总站数据显示，今年以来，上海口岸出入境人员数量持续保持高位运行。前三季度，上海边检机关累计查验出入境人员超3270万人次，同比增长1.2%；查验出入境（港）交通运输工具22万架（艘）次。（每经网）",
