    "description": "央视网消息(焦点访谈)：如果说长征是一部气吞山河的英雄史诗，那么爬雪山、过草地，无疑是这部史诗中最悲壮、最令人刻骨铭心的篇章。长征途中的雪山，空气稀薄、人迹罕至、山高谷深、气候变化无常。翻越途中，许多红军战士累倒、冻僵、长眠在雪山上。",
